export function scenario(a,b,trigger,news=[]){
 if(!a||!b||a.id===b.id)throw Error('Selecciona dos países distintos.');
 const triggers={diplomacy:'Ruptura de conversaciones diplomáticas',trade:'Interrupción del intercambio comercial',incident:'Incidente de seguridad no atribuido'};if(!triggers[trigger])throw Error('Supuesto desconocido.');
 const allied=[a,b].every(p=>p.alliances.some(x=>x.text==='Miembro de la OTAN'));
 const nuclear=[a,b].filter(p=>p.nuclear.text.startsWith('Estado con armamento nuclear')).map(p=>p.name);
 return {title:a.name+' ↔ '+b.name,trigger:triggers[trigger],kind:'Escenarios condicionales redactados con reglas; no pronóstico ni probabilidad.',constraints:[...(allied?['Ambos figuran como miembros de la OTAN en las fichas: la cooperación institucional debe considerarse.']:[]),...(nuclear.length?['Capacidad nuclear clasificada por SIPRI: '+nuclear.join(', ')+'. Debe considerarse como riesgo de consecuencias, no garantía de paz.']:[]),'Los costes humanos y económicos y los canales diplomáticos deben evaluarse; no están cuantificados.'],paths:[{name:'Distensión',condition:'Si las partes aclaran los hechos, mantienen contactos y aceptan mecanismos de verificación.',outcome:'El supuesto inicial puede resolverse mediante negociación o medidas recíprocas.'},{name:'Crisis sostenida',condition:'Si no hay acuerdo, pero ambas partes limitan sus respuestas y mantienen algún canal de comunicación.',outcome:'Puede persistir la presión diplomática o económica sin desembocar necesariamente en enfrentamiento armado.'},{name:'Escalada',condition:'Si se atribuyen responsabilidades erróneamente, se cierran los canales y se encadenan respuestas coercitivas.',outcome:'El riesgo de enfrentamiento podría aumentar. Faltan evidencias específicas para determinar probabilidad, participantes o desenlace.'}],items:news.filter(n=>n.countries.includes(a.id)&&n.countries.includes(b.id)).slice(0,5)};
}
